inline int g_resources{ 0 };

class Quiet
{
public:
    ~Quiet() {}
    virtual int volume() const { return 1; }
};

class Loud : public Quiet
{
public:
    Loud() { ++g_resources; }
    ~Loud() { --g_resources; }
    int volume() const override { return 11; }
};

